/** Scenario `i` (0-19) of a biome: {mech, title, desc, words}, or null for a biome without scenarios. */
export function biomeScenario(biomeId, i, n = 0) {
  const B = BIOME_SCENARIOS[biomeId];
  if (!B) return null;
  const mech = MECHANICS[i], words = { ...B.words, n };
  return { mech, title: B.titles[i], words, desc: DESC[mech].replace(/\{(\w+)\}/g, (_, k) => words[k] ?? k) };
}
